203	        for (int probes = 0; probes < capacity(); probes++) {
204	            byte state = states[index];
205	
206	            if (state == EMPTY) {
207	                int insertionIndex = firstDeletedIndex != NOT_FOUND ? firstDeletedIndex : index;
208	                return new ProbeResult(NOT_FOUND, insertionIndex);
209	            }
210	
211	            if (state == DELETED) {
212	                if (firstDeletedIndex == NOT_FOUND) {
213	                    firstDeletedIndex = index;
214	                }
